    "dbSchema": "-- ユーザーテーブル\nCREATE TABLE users (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  email VARCHAR(255) UNIQUE NOT NULL,\n  password_hash VARCHAR(255),\n  provider VARCHAR(20) NOT NULL DEFAULT 'email', -- 'email' | 'google'\n  google_sub VARCHAR(255) UNIQUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- リフレッシュトークンテーブル\nCREATE TABLE refresh_tokens (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  token_hash VARCHAR(255) NOT NULL,\n  expires_at TIMESTAMPTZ NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- GitHub認証情報テーブル（暗号化保存）\nCREATE TABLE github_credentials (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  github_user_id BIGINT NOT NULL,\n  github_username VARCHAR(255) NOT NULL,\n  access_token_encrypted TEXT NOT NULL, -- AES-256-GCM暗号化\n  scope VARCHAR(500),\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  UNIQUE(user_id)\n);\n\n-- 学習セッションテーブル\nCREATE TABLE learning_sessions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  status VARCHAR(20) NOT NULL DEFAULT 'active', -- 'active' | 'paused' | 'completed' | 'abandoned'\n  current_step VARCHAR(100) NOT NULL DEFAULT 'hearing',\n  accumulated_seconds INTEGER NOT NULL DEFAULT 0,\n  first_started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  last_active_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  completed_at TIMESTAMPTZ,\n  device_info JSONB,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- ヒアリングセッションテーブル\nCREATE TABLE hearing_sessions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  learning_session_id UUID NOT NULL REFERENCES learning_sessions(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  status VARCHAR(20) NOT NULL DEFAULT 'in_progress', -- 'in_progress' | 'completed' | 'skipped'\n  completed_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- ヒアリング回答テーブル\nCREATE TABLE hearing_answers (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  hearing_session_id UUID NOT NULL REFERENCES hearing_sessions(id) ON DELETE CASCADE,\n  question_number INTEGER NOT NULL CHECK (question_number BETWEEN 1 AND 5),\n  question_text TEXT NOT NULL,\n  answer_text TEXT, -- NULLの場合はスキップ\n  is_skipped BOOLEAN NOT NULL DEFAULT FALSE,\n  answered_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  UNIQUE(hearing_session_id, question_number)\n);\n\n-- ユーザーレベルプロファイルテーブル\nCREATE TABLE user_level_profiles (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  learning_session_id UUID NOT NULL REFERENCES learning_sessions(id) ON DELETE CASCADE,\n  level_estimate VARCHAR(20) NOT NULL, -- 'beginner' | 'intermediate' | 'advanced'\n  occupation VARCHAR(255), -- 個人特定情報は保存しない\n  pc_experience_years INTEGER,\n  programming_experience VARCHAR(50), -- 'none' | 'basic' | 'intermediate' | 'advanced'\n  product_idea_summary TEXT, -- マスキング済み\n  domain_keywords JSONB, -- 職業ドメインキーワード（例: ['research', 'cell_culture']）\n  curriculum JSONB NOT NULL, -- AIが生成した個別カリキュラム\n  estimated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  UNIQUE(learning_session_id)\n);\n\n-- マイルストーン定義テーブル（マスターデータ）\nCREATE TABLE milestone_definitions (\n  id INTEGER PRIMARY KEY,\n  name VARCHAR(100) NOT NULL,\n  description TEXT NOT NULL,\n  step_order INTEGER NOT NULL,\n  github_verification_type VARCHAR(50) -- 'account' | 'repository' | 'commit' | 'pull_request' | 'workflow_run'\n);\n\nINSERT INTO milestone_definitions (id, name, description, step_order, github_verification_type) VALUES\n(1, 'GitHubアカウント作成', 'GitHub OAuth認証によりアカウント存在を確認', 1, 'account'),\n(2, 'リポジトリ作成', 'GitHub APIでリポジトリ作成を確認', 2, 'repository'),\n(3, '最初のコミット', 'GitHub APIでコミット履歴を確認', 3, 'commit'),\n(4, 'プルリクエスト作成', 'GitHub APIでPR作成を確認', 4, 'pull_request'),\n(5, 'CI/CD設定', 'GitHub ActionsワークフローのRunを確認', 5, 'workflow_run');\n\n-- ユーザーマイルストーン達成テーブル\nCREATE TABLE user_milestones (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  learning_session_id UUID NOT NULL REFERENCES learning_sessions(id) ON DELETE CASCADE,\n  milestone_id INTEGER NOT NULL REFERENCES milestone_definitions(id),\n  completed BOOLEAN NOT NULL DEFAULT FALSE,\n  completed_at TIMESTAMPTZ,\n  verified_via_github_api BOOLEAN NOT NULL DEFAULT FALSE,\n  github_api_response JSONB, -- GitHub APIの実レスポンスを保存\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  UNIQUE(learning_session_id, milestone_id)\n);\n\n-- ターミナルセッションテーブル\nCREATE TABLE terminal_sessions (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  learning_session_id UUID NOT NULL REFERENCES learning_sessions(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  process_pid INTEGER, -- node-ptyプロセスPID（Redisでも管理）\n  sandbox_path VARCHAR(500),\n  status VARCHAR(20) NOT NULL DEFAULT 'active', -- 'active' | 'disconnected' | 'terminated'\n  cols INTEGER NOT NULL DEFAULT 80,\n  rows INTEGER NOT NULL DEFAULT 24,\n  reconnect_count INTEGER NOT NULL DEFAULT 0,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  last_active_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- コマンド実行ログテーブル\nCREATE TABLE command_logs (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  terminal_session_id UUID NOT NULL REFERENCES terminal_sessions(id) ON DELETE CASCADE,\n  learning_session_id UUID NOT NULL REFERENCES learning_sessions(id) ON DELETE CASCADE,\n  command_text TEXT NOT NULL,\n  stdout TEXT,\n  stderr TEXT,\n  exit_code INTEGER,\n  is_blocked BOOLEAN NOT NULL DEFAULT FALSE,\n  block_reason VARCHAR(255),\n  consecutive_error_count INTEGER NOT NULL DEFAULT 0,\n  executed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- AI説明生成ログテーブル\nCREATE TABLE ai_explanation_logs (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  learning_session_id UUID NOT NULL REFERENCES learning_sessions(id) ON DELETE CASCADE,\n  step_id VARCHAR(100) NOT NULL,\n  request_type VARCHAR(50) NOT NULL, -- 'explain' | 'simplify' | 'error_help' | 'reexplain'\n  prompt_sent TEXT NOT NULL,\n  response_received TEXT,\n  response_time_ms INTEGER,\n  is_filtered BOOLEAN NOT NULL DEFAULT FALSE,\n  api_error BOOLEAN NOT NULL DEFAULT FALSE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- サンドボックス操作イベントログテーブル\nCREATE TABLE sandbox_events (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  learning_session_id UUID NOT NULL REFERENCES learning_sessions(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  event_type VARCHAR(50) NOT NULL, -- 'click_stop' | 'file_edit' | 'file_save' | 'version_loss' | 'git_demo'\n  step_name VARCHAR(100) NOT NULL,\n  duration_ms INTEGER,\n  metadata JSONB,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- Git理解確認回答テーブル\nCREATE TABLE git_understanding_responses (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  learning_session_id UUID NOT NULL REFERENCES learning_sessions(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  understands BOOLEAN NOT NULL,\n  free_text TEXT,\n  responded_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- 達成証明カードテーブル\nCREATE TABLE certificates (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  learning_session_id UUID NOT NULL REFERENCES learning_sessions(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  github_username VARCHAR(255) NOT NULL,\n  elapsed_seconds INTEGER NOT NULL,\n  completed_at TIMESTAMPTZ NOT NULL,\n  milestone_details JSONB NOT NULL, -- 各マイルストーンの達成時刻\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  UNIQUE(learning_session_id)\n);\n\n-- デバイス競合ログテーブル\nCREATE TABLE device_conflict_logs (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,\n  learning_session_id UUID NOT NULL REFERENCES learning_sessions(id) ON DELETE CASCADE,\n  winning_device_info JSONB,\n  conflicted_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\n\n-- インデックス\nCREATE INDEX idx_learning_sessions_user_id ON learning_sessions(user_id);\nCREATE INDEX idx_learning_sessions_status ON learning_sessions(status);\nCREATE INDEX idx_user_milestones_session ON user_milestones(learning_session_id);\nCREATE INDEX idx_command_logs_terminal_session ON command_logs(terminal_session_id);\nCREATE INDEX idx_ai_explanation_logs_session ON ai_explanation_logs(learning_session_id);\nCREATE INDEX idx_sandbox_events_session ON sandbox_events(learning_session_id);\nCREATE INDEX idx_certificates_id ON certificates(id);",
